from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import outage_refund
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def p(amount="80.00", status="captured"):
    return Payment("pay_1","inv_1",Decimal(amount),status=status,created_at=T0,captured_at=T0)

# partial then full
x=p(); outage_refund(x, "30.00", T0); assert x.refunded_amount==Decimal("30.00") and x.status=="captured"
outage_refund(x, "50.00", T0); assert x.refunded_amount==Decimal("80.00") and x.status=="refunded"
print("partial/full ok")

# over refund
try: outage_refund(p(), "80.01", T0); print("FAIL")
except BillingError as e: print("over:", e.code)

# non-captured
try: outage_refund(p(status="authorized"), "1.00", T0); print("FAIL")
except BillingError as e: print("state:", e.code)

# non-positive
try: outage_refund(p(), "0", T0); print("FAIL")
except BillingError as e: print("nonpos:", e.code)

# approval threshold 1000
try: outage_refund(p("2000.00"), "1000.01", T0); print("FAIL")
except BillingError as e: print("approval:", e.code)
y=p("2000.00"); outage_refund(y,"1000.00",T0); print("at threshold ok")
y=p("2000.00"); outage_refund(y,"1000.01",T0,approved_by="mgr"); print("approved ok")

# idempotency
z=p(); outage_refund(z,"10.00",T0,idempotency_key="k1"); outage_refund(z,"10.00",T0,idempotency_key="k1")
assert z.refunded_amount==Decimal("10.00"); print("idempotent ok")
print("audit:", audit.events("payment_refunded")[-1])
EOF"}

